using namespace std;

class Solution {
public:
    int totalInteractionCost(int n, vector<vector<int>>& edges, vector<int>& groups) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        unordered_map<int, int> total_counts;
        for (int g : groups) total_counts[g]++;
        int total_cost = 0;
        auto dfs = [&](auto& self, int u, int p) -> unordered_map<int, int> {
            unordered_map<int, int> sub_counts;
            sub_counts[groups[u]] = 1;
            for (int v : adj[u]) {
                if (v != p) {
                    auto child_counts = self(self, v, u);
                    for (auto [g, cnt] : child_counts) {
                        total_cost += cnt * (total_counts[g] - cnt);
                        sub_counts[g] += cnt;
                    }
                }
            }
            return sub_counts;
        };
        dfs(dfs, 0, -1);
        return total_cost;
    }
};

import java.util.*;

class Solution {
    private int totalCost = 0;
    private Map<Integer, Integer> totalCounts = new HashMap<>();

    public int totalInteractionCost(int n, int[][] edges, int[] groups) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        totalCounts.clear();
        for (int g : groups) totalCounts.put(g, totalCounts.getOrDefault(g, 0) + 1);
        totalCost = 0;
        dfs(0, -1, adj, groups);
        return totalCost;
    }

    private Map<Integer, Integer> dfs(int u, int p, List<List<Integer>> adj, int[] groups) {
        Map<Integer, Integer> subCounts = new HashMap<>();
        subCounts.put(groups[u], 1);
        for (int v : adj.get(u)) {
            if (v != p) {
                Map<Integer, Integer> childCounts = dfs(v, u, adj, groups);
                for (var entry : childCounts.entrySet()) {
                    int g = entry.getKey(), cnt = entry.getValue();
                    totalCost += cnt * (totalCounts.get(g) - cnt);
                    subCounts.put(g, subCounts.getOrDefault(g, 0) + cnt);
                }
            }
        }
        return subCounts;
    }
}

var totalInteractionCost = function(n, edges, groups) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const totalCounts = new Map();
    for (const g of groups) totalCounts.set(g, (totalCounts.get(g) || 0) + 1);
    let totalCost = 0;
    function dfs(u, p) {
        const subCounts = new Map();
        subCounts.set(groups[u], 1);
        for (const v of adj[u]) {
            if (v !== p) {
                const childCounts = dfs(v, u);
                for (const [g, cnt] of childCounts.entries()) {
                    totalCost += cnt * (totalCounts.get(g) - cnt);
                    subCounts.set(g, (subCounts.get(g) || 0) + cnt);
                }
            }
        }
        return subCounts;
    }
    dfs(0, -1);
    return totalCost;
};
